import numpy as np,pandas as pd, warnings,pickle
from pymatgen.core import Structure,Element
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
warnings.filterwarnings('ignore')
tr=pd.read_csv('/work/nlo_shg_eg_train.csv');po=pd.read_csv('/work/nlo_pool.csv');df=pd.concat([tr,po],ignore_index=True)
elements=sorted({str(e) for p in df.poscar for e in Structure.from_str(p,fmt='poscar').composition.elements})
props=['Z','X','atomic_mass','atomic_radius','atomic_radius_calculated','row','group','mendeleev_no','electron_affinity','ionization_energy','molar_volume','melting_point']

def getprops(e):
 v=[]
 for prop in props:
  try: x=float(getattr(e,prop))
  except: x=0
  v.append(x if np.isfinite(x) else 0)
 for orb in ['s','p','d','f']:
  v.append(sum(n for level,o,n in e.full_electronic_structure if o==orb and (level==e.row if orb in ['s','p'] else level>=e.row-1)))
 return v
props+=['ns','np','nd','nf'] if False else []
propnames=props+['ns','np','nd','nf']
rows=[];meta=[]
for ix,r in df.iterrows():
 s=Structure.from_str(r.poscar,fmt='poscar');sg=SpacegroupAnalyzer(s,symprec=.05); comp=s.composition.fractional_composition
 es=comp.elements;w=np.array([comp[e] for e in es]);pr=np.array([getprops(e) for e in es]);f={}
 for e in elements:f['frac_'+e]=comp[e] if e in [str(el) for el in es] else 0.
 f.update(nelem=len(es),vpa=s.volume/len(s),density=s.density,natoms=len(s),sg=sg.get_space_group_number(),polar=int(sg.get_point_group_symbol() in ['1','2','m','mm2','3','3m','4','4mm','6','6mm']),centro=int(sg.is_laue()))
 for stat,x in [('mean',w@pr),('std',np.sqrt(w@((pr-w@pr)**2))),('min',pr.min(axis=0)),('max',pr.max(axis=0)),('range',np.ptp(pr,axis=0))]:
  for j,p in enumerate(propnames): f[stat+'_'+p]=x[j]
 f['entropy']=-np.sum(w*np.log(w))
 lattice=s.lattice
 abc=np.sort(lattice.abc);f['abc_ratio']=abc[-1]/abc[0];f['abc_ratio2']=abc[1]/abc[0];f['anglemin']=min(lattice.angles);f['anglemax']=max(lattice.angles)
 # Chemically ordered constituents
 ces=sorted(es,key=lambda e:(e.X,e.Z));
 for typ,subset in [('cation',ces[:-1]),('anion',ces[-1:])]:
  if not subset:subset=ces
  ww=np.array([comp[e] for e in subset]);ww/=sum(ww);pp=np.array([getprops(e) for e in subset]);
  for stat,x in [('mean',ww@pp),('std',np.sqrt(ww@((pp-ww@pp)**2)))]:
   for j,p in enumerate(propnames): f[typ+'_'+stat+'_'+p]=x[j]
 # Cation-first-shell bond geometry
 neigh=s.get_all_neighbors(4.8);cn=[];length=[];bondX=[];tensors=[];anis=[];shorts=[];types=[];cosabs=[]
 tensors_by_elem={}
 for site,nbs in zip(s,neigh):
  if not nbs:continue
  mn=min(n.nn_distance for n in nbs); shorts.append(mn)
  shell=[n for n in nbs if n.nn_distance<mn*1.22]
  cn.append(len(shell));lens=np.array([n.nn_distance for n in shell]);length.extend(lens.tolist())
  u=np.array([(n.coords-site.coords)/n.nn_distance for n in shell]);
  ten=np.einsum('ni,nj,nk->ijk',u,u,u)/len(u)
  vals=np.linalg.eigvalsh(u.T@u/len(u));anis.append(vals[-1]-vals[0]);cosabs.append(np.linalg.norm(u.mean(axis=0)))
  for n in shell:bondX.append(abs(n.specie.X-site.specie.X))
  if site.specie==ces[-1]:continue
  tensors.append(ten);types.append(str(site.specie))
  tensors_by_elem.setdefault(str(site.specie),[]).append(ten)
 for name,arr in [('cn',cn),('bondlen',length),('bondX',bondX),('anis',anis),('site_polar',cosabs),('nearest',shorts)]:
  for stat,func in [('mean',np.mean),('std',np.std),('min',np.min),('max',np.max)]:f[name+'_'+stat]=func(arr)
 for n in [2,3,4,5,6,8]:f['cn_frac_'+str(n)]=np.mean(np.array(cn)==n)
 if tensors:
  f['tensor_total']=np.linalg.norm(np.sum(tensors,axis=0))/s.volume
  f['tensor_mean']=np.linalg.norm(np.mean(tensors,axis=0))
  f['tensor_local']=np.mean(np.linalg.norm(tensors,axis=(1,2,3)))
  f['tensor_cancel']=np.linalg.norm(np.sum(tensors,axis=0))/(sum(np.linalg.norm(t) for t in tensors)+1e-8)
  for e in elements:f['tensor_'+e]=np.linalg.norm(np.sum(tensors_by_elem.get(e,[np.zeros((3,3,3))]),axis=0))/s.volume
 rows.append(f);meta.append([s.composition.reduced_formula,sg.get_space_group_symbol()])
 if ix%50==0:print(ix,flush=True)
X=pd.DataFrame(rows).fillna(0);pickle.dump((tr,po,X,meta),open('/tmp/nlo_features.pkl','wb'))
print(X.shape)

import pickle,numpy as np,pandas as pd
from pymatgen.core import Structure
from catboost import CatBoostRegressor
from sklearn.model_selection import GroupKFold
from sklearn.metrics import mean_absolute_error
from sklearn.ensemble import ExtraTreesRegressor
tr,po,X,meta=pickle.load(open('/tmp/nlo_features.pkl','rb'))
cols=[c for c in X if not (c.startswith('frac_') or (c.startswith('tensor_') and c not in ['tensor_total','tensor_mean','tensor_local','tensor_cancel']))]
Y=X[cols].copy()
for group in range(1,19):
 Y['group_frac_'+str(group)]=[sum(s.composition.fractional_composition[e] for e in s.composition.elements if e.group==group) for s in [Structure.from_str(p,fmt='poscar') for p in pd.concat([tr,po]).poscar]]
# stats and structure feature cross validated variants
models={}
for v in ['all','noheavy']:
 cols=[c for c in Y if v=='all' or not any(c.endswith('_'+p) for p in ['Z','atomic_mass','mendeleev_no','molar_volume','melting_point'])]
 for m in ['cat','extra']:
  for target,y in [('gap',tr.band_gap.to_numpy()),('logd',np.log1p(tr.shg.to_numpy()))]:
   model=CatBoostRegressor(iterations=1400,depth=4,learning_rate=.025,l2_leaf_reg=3,loss_function='RMSE',verbose=False,thread_count=3,random_seed=45) if m=='cat' else ExtraTreesRegressor(n_estimators=600,min_samples_leaf=1,max_features=.9,n_jobs=3,random_state=45)
   oo=np.zeros(200)
   for a,b in GroupKFold(5).split(Y.iloc[:200],y,[m[0] for m in meta[:200]]):
    model.fit(Y.iloc[a][cols],y[a]);oo[b]=model.predict(Y.iloc[b][cols])
   model.fit(Y.iloc[:200][cols],y);p=model.predict(Y.iloc[200:][cols]);
   models[v+'_'+m+'_'+target]=(p,oo)
   print(v,m,target,'MAE',mean_absolute_error(y,oo),flush=True)
P=pd.DataFrame({k:v[0] for k,v in models.items()});P['id']=po.candidate_id.to_numpy();P['formula']=po.formula.to_numpy()
for k in P:
 if k.endswith('logd'):P[k]=np.expm1(P[k])
print(P.round(2).to_string(index=False));pickle.dump(models,open('/tmp/nlo_group_preds.pkl','wb'))

